B=Path(__file__).resolve().parent.parent;arm=int(sys.argv[1]);attempt=int(sys.argv[2]);assert arm in(2,3,4)and attempt>=1;O=B/('current-read32-arm-%d-probe-r%d'%(arm,attempt));O.mkdir();C=B/'current-read-window32-collection-preparation-r2';identity=json.loads((B/('current-read32-arm-%d-launch-r1/stdout.json'%arm)).read_text());release=json.loads((B/'current-read-window32-controller-preparation-r1/root-release-r2/release.json').read_text());gate=B/('current-read32-arm-%d-prior-gate-r1/collection-gate.json'%(arm-1));source=(C/'inspect_closed_current_read32.py').read_text();args=['--arm',str(arm),'--release-sha256','35652d5dd4175e2f7fff500147ce084a41d9ae7a3c6951b9c67374b780ec05d0','--controller-sha256',release['controllerSha256'],'--controller-pid',str(identity['pid']),'--controller-start-ticks',str(identity['startTicks']),'--controller-argv-sha256',identity['observedCommandSha256'],'--prior-collection-sha256',hashlib.sha256(gate.read_bytes()).hexdigest()];(O/'REGISTRATION.json').write_text(json.dumps(dict(atUTC=datetime.datetime.now(datetime.timezone.utc).isoformat(),arguments=args,executedSourceSha256=hashlib.sha256(source.encode()).hexdigest(),boundedControlOnly=True,noWorkloadOrSignals=True),indent=2)+'\n');(O/'executed-probe.py').write_text(source);spec=importlib.util.spec_from_file_location('current_read32_probe_ssh',C/'remote_current.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);r=m.run(shlex.join(['python3','-B','-c',source,*args]),timeout=45);(O/'stdout.json').write_text(r.stdout);(O/'stderr').write_text(r.stderr);(O/'EXECUTION.json').write_text(json.dumps(dict(exitCode=r.returncode,stdoutSha256=hashlib.sha256(r.stdout.encode()).hexdigest(),stderrSha256=hashlib.sha256(r.stderr.encode()).hexdigest()),indent=2)+'\n');assert r.returncode==0;d=json.loads(r.stdout);print(json.dumps({k:d.get(k)for k in['state','closedGate','controller','allFourOwnedJvmsStrictlyPidAbsent','schedulerTimingValidReported','readWindow']}))
